import { test, expect } from '@playwright/test';

test.describe('Product List Display', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.saucedemo.com');
    await page.fill('[data-test="username"]', 'standard_user');
    await page.fill('[data-test="password"]', 'secret_sauce');
    await page.click('[data-test="login-button"]');
  });

  test('should display exactly 6 product cards', async ({ page }) => {
    const productCards = await page.getByRole('listitem', { name: /inventory_item/i });
    expect(await productCards.count()).toBe(6);
  });

  test('each product card should have a name and price', async ({ page }) => {
    const productCards = await page.getByRole('listitem', { name: /inventory_item/i });

    for (let i = 0; i < await productCards.count(); i++) {
      const card = productCards.nth(i);
      const name = await card.getByText(/inventory_item_name/i);
      const price = await card.getByText(/inventory_item_price/i);

      expect(await name.textContent()).not.toBe('');
      expect(await price.textContent()).toMatch(/^\$/);
    }
  });
});
